// Copyright (C) 2017-2024 Smart code 203358507

@import (reference) '~stremio/common/screen-sizes.less';
@import (reference) '~@stremio/stremio-colors/less/stremio-colors.less';

@font-face {
    font-family: 'PlusJakartaSans';
    src: url('/assets/fonts/PlusJakartaSans.ttf') format('truetype');
}

@font-face {
    font-family: 'TwemojiFlags';
    src: url('/assets/fonts/TwemojiFlags.woff2') format('woff2');
    unicode-range: U+1F1E6-1F1FF;
}

:global {
    @import (once, less) '~stremio/common/animations.less';
    @import (once, less) '~stremio-router/styles.css';
}

// iOS pads the bottom inset more than needed, so we deduce the actual inset size when using the webapp
@calculated-bottom-safe-inset: if(@webos = true, 0rem, ~"min(env(safe-area-inset-bottom, 0rem), max(1rem, calc(var(--viewport-height-diff) - env(safe-area-inset-top, 0rem))))");

// Viewport sizes
@viewport-width: ~"100vw";
@viewport-height: ~"100vh";

// HTML sizes
// Chromium 68 does not parse max() in calc(), so the webOS build uses the
// viewport fallback directly while modern builds keep dynamic sizing.
@html-width: if(@webos = true, @viewport-width, ~"calc(max(var(--small-viewport-width), var(--dynamic-viewport-width)))");
@html-height: if(@webos = true, @viewport-height, ~"calc(max(var(--small-viewport-height), var(--dynamic-viewport-height)))");
@html-standalone-width: if(@webos = true, @viewport-width, ~"calc(max(100%, var(--large-viewport-width)))");
@html-standalone-height: if(@webos = true, @viewport-height, ~"calc(max(100%, var(--large-viewport-height)))");

// Safe area insets
// Chromium 68 cannot resolve env() stored in custom properties. TV has no notch;
// T2.8 can adjust these constants for overscan after validating the TV layout.
@safe-area-inset-top: if(@webos = true, 0rem, env(safe-area-inset-top, 0rem));
@safe-area-inset-right: if(@webos = true, 0rem, env(safe-area-inset-right, 0rem));
@safe-area-inset-bottom: if(@webos = true, 0rem, env(safe-area-inset-bottom, 0rem));
@safe-area-inset-left: if(@webos = true, 0rem, env(safe-area-inset-left, 0rem));

@top-overlay-size: 5.25rem;
@bottom-overlay-size: 0rem;
@overlap-size: 3rem;
@transparency-gradient-pad: 6rem;

:root {
    --landscape-shape-ratio: 0.5625;
    --poster-shape-ratio: 1.464;
    --scroll-bar-size: 6px;
    --horizontal-nav-bar-size: 5.5rem;
    --vertical-nav-bar-size: 6rem;
    --focus-outline-size: 2px;
    --color-facebook: #1877F1;
    --color-x: #000000;
    --color-reddit: #FF4500;
    --color-imdb: #f5c518;
    --color-trakt: rgb(255, 255, 255);
    --color-placeholder: #60606080;
    --color-placeholder-text: @color-surface-50;
    --color-placeholder-background: @color-surface-dark5-20;
    --primary-background-color: rgba(12, 11, 17, 1);
    --secondary-background-color: rgba(26, 23, 62, 1);
    --primary-foreground-color: rgba(255, 255, 255, 0.9);
    --secondary-foreground-color: rgb(12, 11, 17, 1);
    --primary-accent-color: rgb(123, 91, 245);
    --secondary-accent-color: rgba(34, 179, 101, 1);
    --tertiary-accent-color: rgba(246, 199, 0, 1);
    --quaternary-accent-color: rgba(18, 69, 166, 1);
    --overlay-color: rgba(255, 255, 255, 0.05);
    --modal-background-color: rgba(15, 13, 32, 1);
    --outer-glow: 0px 0px 15px rgba(123, 91, 245, 0.37);
    --warning-accent-color: rgba(255, 165, 0, 1);
    --danger-accent-color: rgba(220, 38, 38, 1);  
    --border-radius: 0.75rem;
    --top-overlay-size: @top-overlay-size;
    --bottom-overlay-size: @bottom-overlay-size;
    --overlap-size: @overlap-size;
    --transparency-gradient-pad: @transparency-gradient-pad;
    --safe-area-inset-top: @safe-area-inset-top;
    --safe-area-inset-right: @safe-area-inset-right;
    --safe-area-inset-bottom: @safe-area-inset-bottom;
    --safe-area-inset-left: @safe-area-inset-left;
    --dynamic-viewport-width: @viewport-width;
    --dynamic-viewport-height: @viewport-height;
    --large-viewport-width: @viewport-width;
    --large-viewport-height: @viewport-height;
    --small-viewport-width: @viewport-width;
    --small-viewport-height: @viewport-height;
    --viewport-height-diff: calc(100vh - 100vh);

    @supports (height: 100dvh) {
        --dynamic-viewport-width: 100dvw;
        --dynamic-viewport-height: 100dvh;
    }

    @supports (height: 100lvh) {
        --large-viewport-width: 100lvw;
        --large-viewport-height: 100lvh;
    }

    @supports (height: 100svh) {
        --small-viewport-width: 100svw;
        --small-viewport-height: 100svh;
    }

    @supports (height: 100lvh) and (height: 100svh) {
        --viewport-height-diff: calc(100lvh - 100svh);
    }

    @media (display-mode: standalone) {
        --safe-area-inset-bottom: @calculated-bottom-safe-inset;
    }
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-size: 1rem;
    font-family: inherit;
    border: none;
    outline: none;
    list-style: none;
    user-select: none;
    text-decoration: none;
    appearance: none;
    background: none;
    box-shadow: none;
    overflow: hidden;
    word-break: break-word;
    scrollbar-width: thin;
    scrollbar-color: var(--overlay-color) transparent;
}

::-webkit-scrollbar {
    width: var(--scroll-bar-size);
    height: var(--scroll-bar-size);
}

::-webkit-scrollbar-thumb {
    border-radius: var(--scroll-bar-size);
    background-color: var(--overlay-color);

    &:hover {
        background-color: var(--primary-accent-color);
    }
}

::-webkit-scrollbar-track {
    background-color: transparent;
}

svg {
    overflow: visible;
}

::view-transition-old(root),
::view-transition-new(root) {
    animation-duration: 0.15s;
}

html {
    width: @html-width;
    height: @html-height;
    font-family: 'PlusJakartaSans', 'Arial', 'Helvetica', 'TwemojiFlags', 'sans-serif';
    overflow: auto;
    overscroll-behavior: none;
    user-select: none;
    touch-action: manipulation;
    background-color: var(--primary-background-color);
    -webkit-tap-highlight-color: transparent;

    @media (display-mode: standalone) {
        width: @html-standalone-width;
        height: @html-standalone-height;
        -webkit-touch-callout: none;
    }

    body {
        width: 100%;
        height: 100%;
        background: linear-gradient(41deg, var(--primary-background-color) 0%, var(--secondary-background-color) 100%);
        -webkit-font-smoothing: antialiased;

        :global(#app) {
            position: relative;
            z-index: 0;
            width: 100%;
            height: 100%;

            .toasts-container {
                position: absolute;
                top: calc(1.2 * var(--horizontal-nav-bar-size) + var(--safe-area-inset-top));
                right: var(--safe-area-inset-right);
                bottom: calc(1.2 * var(--horizontal-nav-bar-size) + var(--safe-area-inset-bottom, 0rem));
                left: auto;
                z-index: 1;
                padding: 0 calc(0.5 * var(--horizontal-nav-bar-size));
                overflow: visible;
                scrollbar-width: none;
                pointer-events: none;

                &::-webkit-scrollbar {
                    display: none;
                }
            }

            .tooltip-container {
                height: 2.5rem;
                display: flex;
                align-items: center;
                justify-content: center;
                padding: 0 1.5rem;
                font-size: 1rem;
                color: var(--primary-foreground-color);
                border-radius: var(--border-radius);
                background-color: var(--modal-background-color);
                box-shadow: var(--outer-glow);
                transition: opacity 0.1s ease-out;
            }

            .updater-banner-container {
                z-index: 1;
                position: absolute;
                left: 0;
                right: 0;
                bottom: 0;

                @media only screen and (max-width: @minimum) {
                    left: 0.5rem;
                    right: 0.5rem;
                    bottom: calc(var(--vertical-nav-bar-size) + var(--safe-area-inset-bottom) + 0.5rem);
                }
            }
        }
    }
}

@media only screen and (min-width: @xxlarge) {
    html {
        font-size: 18px;
    }
}

@media only screen and (max-width: @xxlarge) {
    html {
        font-size: 16px;
    }
}

@media only screen and (max-width: @large) {
    html {
        font-size: 15px;
    }
}

@media only screen and (max-width: @medium) {
    html {
        font-size: 14px;
    }
}

@media only screen and (max-width: @xsmall) {
    html {
        body {
            :global(#app) {
                .toasts-container {
                    padding: 0 1rem;
                }

                .tooltip-container {
                    display: none;
                }
            }
        }
    }
}

@media only screen and (max-width: @minimum) {
    :root {
        --bottom-overlay-size: 6rem;
    }
}

common/animations.less:
// Copyright (C) 2017-2023 Smart code 203358507

:global(.animation-fade-in) {
    :local {
        animation-name: fade-in;
    }

    animation-timing-function: ease-in-out;
    animation-duration: 350ms;

    @media (prefers-reduced-motion) {
        :local {
            animation-name: fade-in-no-motion;
        }
    }
}

@keyframes fade-in {
    0% {
        opacity: 0;
        transform: translateY(4px);
    }

    40% {
        opacity: 0;
        transform: translateY(4px);
    }

    70% {
        opacity: 0.6;
        transform: translateY(2px);
    }

    100% {
        opacity: 1;
        transform: translateY(0);
    }
}

:global(.animation-slide-up) {
    :local {
        animation-name: slide-up;
    }

    animation-timing-function: ease-out;
    animation-duration: 0.1s;
}

@keyframes slide-up {
    0% {
        transform: translateY(100%);
    }

    100% {
        transform: translateY(0%);
    }
}

.slide-left-enter {
    transform: translateX(100%);
}

.slide-left-active {
    transform: translateX(0%);
    transition: transform 0.3s cubic-bezier(0.32, 0, 0.67, 0);
}

.slide-left-exit {
    transform: translateX(100%);
}

.slide-up-enter {
    transform: translateY(100%);
}

.slide-up-active {
    transform: translateY(0%);
    transition: transform 0.3s cubic-bezier(0.32, 0, 0.67, 0);
}

.slide-up-exit {
    transform: translateY(100%);
}

.fade-enter {
    opacity: 0;
}

.fade-active {
    opacity: 1;
    transition: opacity 0.1s cubic-bezier(0.32, 0, 0.67, 0);
}

.fade-exit {
    opacity: 0;
}

@keyframes fade-in-no-motion {
    0% {
        opacity: 0;
    }

    40% {
        opacity: 0;
    }

    70% {
        opacity: 0.6;
    }

    100% {
        opacity: 1;
    }
}

common/screen-sizes.less:
// Copyright (C) 2017-2023 Smart code 203358507

@minimum: 640px;
@xxsmall: 800px;
@xsmall: 1000px;
@small: 1300px;
@medium: 1600px;
@normal: 1900px;
@large: 2200px;
@xlarge: 2500px;
@xxlarge: 2800px;
@xxxlarge: 3800px;

@small-phone-landscape-size: 400px;
@small-phone-portrait-size: 700px;

@phone-landscape-size: 500px;
@phone-portrait-size: 1000px;

@small-phone-landscape: ~"screen and (max-width: @{small-phone-portrait-size}) and (max-height: @{small-phone-landscape-size}) and (orientation: landscape)";
@small-phone-portrait: ~"screen and (max-width: @{small-phone-landscape-size}) and (max-height: @{small-phone-portrait-size}) and (orientation: portrait)";

@phone-landscape: ~"screen and (max-width: @{phone-portrait-size}) and (max-height: @{phone-landscape-size}) and (orientation: landscape)";
@phone-portrait: ~"screen and (max-width: @{phone-landscape-size}) and (max-height: @{phone-portrait-size}) and (orientation: portrait)";

// less-loader overrides this value for the webOS build. Chromium 68 reports
// generic gap support because Grid supports it, but Flexbox gap is unavailable.
@webos: false;

.tv-flex-gap(@row-gap, @column-gap: @row-gap, @direction: row) {
    gap: @row-gap @column-gap;

    & when (@webos = true) {
        > * + * {
            margin-top: 0;
            margin-left: 0;
        }

        & when (@direction = row) {
            > * + * {
                margin-left: @column-gap;
            }
        }

        & when (@direction = column) {
            > * + * {
                margin-top: @row-gap;
            }
        }
    }
}

.tv-flex-gap-wrap(@row-gap, @column-gap: @row-gap) {
    gap: @row-gap @column-gap;

    & when (@webos = true) {
        // Trim the final child margin from the container's outer box.
        margin-right: -@column-gap;
        margin-bottom: -@row-gap;

        > * {
            margin-right: @column-gap;
            margin-bottom: @row-gap;
        }
    }
}

.tv-flex-gap-reset() when (@webos = true) {
    > * + * {
        margin-top: 0;
        margin-left: 0;
    }
}

common/tv-focus.less:
// webOS focus is the 5-way cursor, independent of input modality.
@import (reference) '~stremio/common/screen-sizes.less';

@tv-focus-color: #fff;
@tv-focus-size: 4px;
@tv-focus-offset: -4px;

.tv-focus-ring() when (@webos = true) {
    outline: @tv-focus-size solid @tv-focus-color;
    outline-offset: @tv-focus-offset;
}

.tv-focus() when (@webos = true) {
    &:focus {
        .tv-focus-ring();
    }
}

App/GamepadModal/styles.less:
// Copyright (C) 2017-2026 Smart code 203358507

@import (reference) '~@stremio/stremio-colors/less/stremio-colors.less';
@import (reference) '~stremio/common/tv-focus.less';
@import (reference) '~stremio/common/screen-sizes.less';

.gamepad-modal {
    position: absolute;
    top: 0;
    bottom: 0;
    left: 0;
    right: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 100;

    .backdrop {
        position: absolute;
        top: 0;
        bottom: 0;
        left: 0;
        right: 0;
        background-color: @color-background-dark5-40;
        cursor: pointer;
    }

    .container {
        position: relative;
        display: flex;
        flex-direction: column;
        .tv-flex-gap(1rem, 1rem, column);
        max-height: 90%;
        max-width: 72rem;
        width: 92%;
        border-radius: var(--border-radius);
        background-color: var(--modal-background-color);
        box-shadow: var(--outer-glow);
        overflow: hidden;

        .header {
            flex: none;
            display: flex;
            justify-content: space-between;
            align-items: center;
            height: 5rem;
            padding-left: 2.5rem;
            padding-right: 1rem;

            .title {
                position: relative;
                font-size: 1.5rem;
                font-weight: 500;
                color: var(--primary-foreground-color);
            }

            .close-button {
                position: relative;
                width: 3rem;
                height: 3rem;
                padding: 0.5rem;
                border-radius: var(--border-radius);
                z-index: 2;

                .icon {
                    display: block;
                    width: 100%;
                    height: 100%;
                    color: var(--primary-foreground-color);
                    opacity: 0.4;
                }

                &:hover, &:focus {
                    .icon {
                        opacity: 1;
                        color: var(--primary-foreground-color);
                    }
                }

                &:focus {
                    outline-color: var(--primary-foreground-color);
                }
            }
        }

        .content {
            position: relative;
            display: flex;
            flex-direction: column;
            align-items: center;
            .tv-flex-gap(3rem, 3rem, column);
            padding: 0 3rem;
            padding-bottom: 3rem;
            flex: 1;
            min-height: 0;
            overflow-y: auto;
        }
    }

    @keyframes draw-stroke {
        from { stroke-dashoffset: 2000; }
        to { stroke-dashoffset: 0; }
    }

    @keyframes draw-line {
        from { stroke-dashoffset: 800; }
        to { stroke-dashoffset: 0; }
    }

    @keyframes fade-in {
        from { opacity: 0; }
        to { opacity: 1; }
    }

    .diagram {
        flex: none;
        width: 100%;
        max-width: 48rem;
        height: auto;

        .anim-body {
            stroke-dasharray: 2000;
            stroke-dashoffset: 0;
            animation: draw-stroke 1.4s ease-in-out;
        }

        .anim-controls {
            animation: fade-in 0.6s ease-out 1s both;
        }

        .anim-lines {
            line {
                stroke-dasharray: 800;
                stroke-dashoffset: 0;
                animation: draw-line 0.8s ease-out 1.6s both;
            }
            circle {
                animation: fade-in 0.3s ease-out 2s both;
            }
        }

        .anim-labels {
            animation: fade-in 0.5s ease-out 2.2s both;
        }
    }

    .sections {
        flex: none;
        display: flex;
        flex-direction: row;
        .tv-flex-gap(5rem, 5rem, row);
        width: 100%;
        max-width: 56rem;
        overflow: visible;
    }

    .section {
        flex: 1;
        display: flex;
        flex-direction: column;
        .tv-flex-gap(1.2rem, 1.2rem, column);
        overflow: visible;
    }

    .section-title {
        font-size: 1rem;
        font-weight: 600;
        color: var(--primary-foreground-color);
        margin-bottom: 0.4rem;
        text-transform: uppercase;
        letter-spacing: 0.05em;
        opacity: 0.7;
    }

    .mapping {
        display: grid;
        grid-template-columns: auto 1.2rem 1fr;
        align-items: center;
        column-gap: 0.5rem;
    }

    .kbd {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        min-width: 2rem;
        height: 1.8rem;
        padding: 0 0.5rem;
        border-radius: 0.35rem;
        background-color: rgba(123, 91, 245, 0.15);
        border: 1px solid rgba(123, 91, 245, 0.3);
        box-shadow: none;
        color: #c4b5fd;
        font-size: 0.8rem;
        font-weight: 600;
        font-family: inherit;
    }

    .dir {
        color: #8b7faa;
        font-size: 1rem;
    }

    .action {
        color: var(--primary-foreground-color);
        font-size: 0.9rem;
        opacity: 0.8;
    }
}

@media only screen and (max-width: 640px) {
    .gamepad-modal {
        .container {
            max-width: 95%;
        }

        .sections {
            flex-direction: column;
            .tv-flex-gap(2rem, 2rem, column);
        }
    }
}

// Keep the TV cursor visible through local hover/selected overrides.
.gamepad-modal .container .header .close-button {
    .tv-focus();
}

