@media only screen and (max-width: @minimum) {
    .main-nav-bars-container {
        .nav-content-container {
            left: 0;
            bottom: var(--vertical-nav-bar-size);
        }

        .vertical-nav-bar {
            top: initial;
        }
    }
}

components/MetaItem/styles.less:
// Copyright (C) 2017-2024 Smart code 203358507

@import (reference) '~@stremio/stremio-colors/less/stremio-colors.less';
@import (reference) '~stremio/common/tv-focus.less';
@import (reference) '~stremio/common/screen-sizes.less';

:import('~stremio/components/Popup/styles.less') {
    popup-menu-container: menu-container;
}

:import('~stremio/components/Multiselect/styles.less') {
    multiselect-menu-container: menu-container;
    multiselect-option-container: option-container;
    multiselect-option-label: label;
}

@play-icon-size: 4rem;

.meta-item-container {
    position: relative;
    padding: 1rem;
    overflow: visible;

    &:hover, &:focus-within, &:global(.active), &:global(.selected) {
        outline-style: none;
        transition: background-color 100ms ease-out;

        .poster-container {
            box-shadow: 0 0 0 0.2rem var(--primary-foreground-color);

            .dismiss-icon-layer {
                opacity: 1;
            }

            .poster-image-layer {
                transform: scale(1.05);
            }

            .play-icon-layer {
                .play-icon-outer {
                    color: transparent;
                }

                .play-icon-background {
                    background-color: var(--secondary-accent-color);
                    opacity: 1;
                }
            }
        }

        .menu-label-container {
            opacity: 1;
        }
    }

    .meta-item-link {
        display: block;
        overflow: visible;

        &:focus {
            outline-style: none;
        }

        @media (pointer: coarse) {
            &:active:not(:global(.active)) {
                scale: none;
            }
        }
    }

    &.poster-shape-poster {
        .poster-container {
            padding-top: calc(100% * var(--poster-shape-ratio));
        }
    }

    &.poster-shape-square {
        .poster-container {
            padding-top: 100%;
        }
    }

    &.poster-shape-landscape {
        .poster-container {
            padding-top: calc(100% * var(--landscape-shape-ratio));
        }
    }

    &:active:not(:global(.active)) {
        scale: none;

        .poster-container {
            scale: 0.95;
        }
    }

    .poster-container {
        position: relative;
        z-index: 0;
        background-color: var(--overlay-color);
        border-radius: var(--border-radius);
        transition: scale 100ms ease-out;

        &:global(.poster-change-cursor) {
            .poster-image-layer {
                &:hover {
                    cursor: zoom-in;
                }
            }
        }

        .dismiss-icon-layer {
            z-index: -2;
            position: absolute;
            top: 0.5rem;
            left: 0.5rem;
            display: flex;
            align-items: center;
            justify-content: center;
            height: 1.5rem;
            width: 1.5rem;
            border-radius: 100%;
            opacity: 0;
            transition: opacity 0.1s ease-in;

            .dismiss-icon {
                z-index: 1;
                position: relative;
                height: 1.25rem;
                width: 1.25rem;
                color: var(--primary-foreground-color);
                opacity: 0.8;
            }

            .dismiss-icon-backdrop {
                z-index: 0;
                position: absolute;
                top: 0;
                bottom: 0;
                left: 0;
                right: 0;
                background-color: var(--primary-background-color);
                opacity: 0.6;
            }
        }

        .watched-icon-layer {
            position: absolute;
            top: 0;
            left: 0;
            display: flex;
            justify-content: center;
            align-items: center;
            width: 1.5rem;
            height: 1.5rem;
            background-color: var(--primary-accent-color);
            border-radius: 50%;
            margin: 0.5rem;

            .watched-icon {
                width: 0.75rem;
                height: 0.75rem;
                color: var(--primary-foreground-color);
            }
        }

        .poster-image-layer {
            position: absolute;
            top: 0;
            right: 0;
            bottom: 0;
            left: 0;
            z-index: -3;
            display: flex;
            flex-direction: row;
            align-items: center;
            justify-content: center;
            transition: transform 0.1s ease-out;

            .poster-image {
                flex: none;
                width: 100%;
                height: 100%;
                object-position: center;
                object-fit: cover;
                opacity: 0.9;
                overflow-clip-margin: unset;
            }

            .placeholder-icon {
                flex: none;
                width: 80%;
                height: 50%;
                color: var(--primary-foreground-color);
                opacity: 0.2;
            }
        }

        .play-icon-layer {
            z-index: -2;
            position: absolute;
            top: 50%;
            left: 50%;
            margin-top: calc(@play-icon-size / -2);
            margin-left: calc(@play-icon-size / -2);
            display: flex;
            align-items: center;
            justify-content: center;
            height: @play-icon-size;
            width: @play-icon-size;
            transition: transform 0.1s ease-out;

            .play-icon {
                z-index: 2;
                position: relative;
                height: 2.25rem;
                width: 2.25rem;
                color: var(--primary-foreground-color);
            }

            .play-icon-outer {
                z-index: 1;
                position: absolute;
                top: 0;
                bottom: 0;
                left: 0;
                right: 0;
                color: var(--primary-foreground-color);
                box-shadow: 0 0 0 0.15rem currentColor inset;
                border-radius: 100%;
                transition: color 0.1s ease-in;
            }

            .play-icon-background {
                z-index: 0;
                position: absolute;
                top: 0;
                bottom: 0;
                left: 0;
                right: 0;
                background-color: var(--primary-background-color);
                border-radius: 100%;
                opacity: 0.4;
                transition: all 0.1s ease-in;
            }

            &:hover {
                transform: scale(1.1);
            }
        }

        .progress-bar-layer {
            z-index: -1;
            position: absolute;
            bottom: 1rem;
            left: 1rem;
            right: 1rem;
            height: 0.45rem;
            border-radius: 0.45rem;
            overflow: hidden;

            .progress-bar {
                position: relative;
                height: 100%;
                background-color: var(--primary-foreground-color);
            }
            
            .progress-bar-background {
                position: absolute;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
                background-color: var(--primary-foreground-color);
                opacity: 0.3;
            }
        }

        .new-videos {
            z-index: -1;
            position: absolute;
            top: 0;
            right: 0;
            overflow: visible;

            .layer {
                position: absolute;
                display: flex;
                align-items: center;
                justify-content: center;
                height: 1.25rem;
                width: 2.25rem;
                border-radius: 0.25rem;

                &:nth-child(1) {
                    top: 0.5rem;
                    right: 0.5rem;
                    background-color: var(--primary-foreground-color);
                    opacity: 0.4;
                }

                &:nth-child(2) {
                    top: 0.75rem;
                    right: 0.75rem;
                    background-color: var(--primary-foreground-color);
                    opacity: 0.6;
                }

                &:nth-child(3) {
                    top: 1rem;
                    right: 1rem;
                    background-color: var(--primary-foreground-color);
                }

                .icon {
                    height: 0.8rem;
                    width: 0.8rem;
                    color: var(--primary-accent-color);
                }

                .label {
                    font-size: 0.8rem;
                    font-weight: 600;
                    color: var(--primary-accent-color);
                }
            }
        }
    }

    .title-bar-container {
        display: flex;
        flex-direction: row;
        align-items: center;
        height: 4rem;
        overflow: visible;

        &.has-menu {
            .title-label {
                padding-left: 1.5rem;
                padding-right: 1.5rem;
            }
        }

        .title-label {
            flex: 1;
            padding-left: 1.5rem;
            font-weight: 600;
            text-align: center;
            color: var(--primary-foreground-color);
            display: -webkit-box;
            -webkit-line-clamp: 2;
            -webkit-box-orient: vertical;
            overflow: hidden;

            &:only-child {
                padding: 0 0.5rem;
            }
        }
    }

    .menu-label-container {
        position: absolute;
        right: 1rem;
        bottom: 1rem;
        z-index: 1;
        flex: none;
        width: 1.5rem;
        height: 4rem;
        padding: 1rem 0;
        background-color: transparent;
        opacity: 0;
        transform: translateX(1rem);
        transition: opacity 0.1s ease-out;

        .icon {
            display: block;
            width: 100%;
            height: 100%;
            color: var(--primary-foreground-color);
            opacity: 0.6;
        }

        .popup-menu-container {
            width: auto;

            .multiselect-menu-container {
                min-width: 9rem;
                max-width: 14rem;

                .multiselect-option-container {
                    padding: 1rem 1.5rem;

                    &:hover, &:focus {
                        outline: none;
                        background-color: var(--overlay-color);
                    }

                    .multiselect-option-label {
                        font-weight: 500;
                        color: var(--primary-foreground-color);
                        opacity: 0.8;
                    }
                }
            }
        }
    }
}

@media only screen and (max-width: @minimum) {
    .meta-item-container {
        padding: 0.5rem;

        .menu-label-container {
            right: 0.5rem;
            bottom: 0.5rem;
        }

        .title-bar-container {
            margin-top: 0.5rem;
        }
    }
}

// The main link delegates its cursor to the poster; menu actions own theirs.
.meta-item-container when (@webos = true) {
    .meta-item-link:focus {
        outline: none;
        .poster-container {
            // Replace the legacy focus-within halo while this link owns focus.
            box-shadow: none;
            .tv-focus-ring();
        }
    }
    .menu-label-container {
        .tv-focus();
        .popup-menu-container .multiselect-menu-container .multiselect-option-container {
            .tv-focus();
        }
    }
}

components/MetaPreview/styles.less:
// Copyright (C) 2017-2023 Smart code 203358507

@import (reference) '~@stremio/stremio-colors/less/stremio-colors.less';
@import (reference) '~stremio/common/tv-focus.less';
@import (reference) '~stremio/common/screen-sizes.less';

.meta-preview-container {
    position: relative;
    z-index: 0;
    display: flex;
    flex-direction: column;

    &.compact {
        .meta-info-container {
            .logo, .logo-placeholder {
                width: 100%;
                height: 6rem;
            }

            .runtime-release-info-container {
                justify-content: space-between;

                .runtime-label, .release-info-label {
                    margin: 1rem 0.4rem;
                }
            }

            .description-container {
                max-height: none;
            }
        }

        .action-buttons-container {
            justify-content: space-between;

            .action-button:not(:last-child), .group-container:not(:last-child) {
                margin-right: 0;
            }
        }
    }

    .background-image-layer {
        position: absolute;
        top: -10px;
        right: -10px;
        bottom: -10px;
        left: -10px;
        z-index: -1;

        .background-image {
            display: block;
            width: 100%;
            height: 100%;
            object-fit: cover;
            object-position: center;
            filter: blur(10px);
            opacity: 0.3;
        }
    }

    .meta-info-container {
        flex: 1;
        align-self: stretch;
        overflow-y: auto;

        &:not(:hover) {
            scrollbar-color: transparent transparent;

            &::-webkit-scrollbar-thumb, &::-webkit-scrollbar-track {
                background-color: transparent;
            }
        }

        .logo, .logo-placeholder {
            display: block;
            max-width: 100%;
            margin-bottom: 2rem;
        }

        .logo {
            height: 9rem;
            object-fit: contain;
            object-position: center;
        }

        .logo-placeholder {
            font-size: 1.7rem;
            color: @color-surface-light5-90;
        }

        .runtime-release-info-container {
            display: flex;
            flex-direction: row;
            align-items: center;
            flex-wrap: wrap;
            margin-top: 1rem;

            .runtime-label, .release-info-label {
                flex: 0 1 auto;
                margin-right: 3rem;
                font-size: 1.25rem;
                font-weight: 600;
                color: var(--primary-foreground-color);
            }

            .imdb-button-container {
                flex: 0 1 auto;
                display: flex;
                flex-direction: row;
                align-items: center;
                border-radius: 0.5rem;
                border: var(--focus-outline-size) solid transparent;
                padding: 0rem 0.5rem;

                &:focus {
                    outline: none;
                    border: var(--focus-outline-size) solid @color-surface-light5;
                }

                .label {
                    flex: 0 1 auto;
                    margin-right: 1rem;
                    font-size: 1.25rem;
                    font-weight: 600;
                    color: var(--primary-foreground-color);
                }

                .icon {
                    flex: none;
                    width: 3rem;
                    height: 3rem;
                    color: var(--color-imdb);
                }
            }
        }

        .description-container {
            margin-top: 1rem;
            font-size: 1rem;
            font-weight: 400;
            line-height: 2em;
            color: var(--primary-foreground-color);
            .label-container {
                text-transform: uppercase;
                font-size: 0.95rem;
                font-weight: 700;
                color: var(--primary-foreground-color);
                opacity: 0.3;
            }
        }

        .meta-links {
            margin-top: 1.5rem;
        }
    }

    .action-buttons-container {
        flex: none;
        align-self: stretch;
        display: flex;
        flex-direction: row;
        align-items: flex-end;
        flex-wrap: wrap;
        padding-top: 3.5rem;
        overflow: visible;

        .label {
            position: absolute;
            top: -3rem;
            left: 0;
            opacity: 0;
            transition: opacity 0.3s ease; 
            text-align: center;
            color: var(--primary-foreground-color);
            overflow: visible;
        }

        &:not(:last-child) {
            margin-right: 1rem;
        }

        &:hover {
            .label {
                opacity: 0.7;
            }
        }
    
        .action-button {
            flex: none;
            width: 4rem;
            height: 4rem;
            margin-bottom: 1rem;

            &:global(.wide) {
                width: auto;
                padding: 0 2rem;
                border-radius: 4rem;
            }

            &:not(:last-child) {
                margin-right: 1rem;
            }

            &.show-button {
                &:hover, &:focus {
                    background-color: var( --secondary-accent-color);
                    outline: none;
                }
            }
        }
    
        .group-container {
            margin-bottom: 1rem;

            &:global(.wide) {
                width: auto;
                padding: 0 2rem;
                border-radius: 4rem;
            }

            &:not(:last-child) {
                margin-right: 1rem;
            }
        }
    }
}

.share-prompt {
    width: 30rem;
}


@media @phone-landscape {
    .meta-preview-container {
        .meta-info-container {
            .logo {
                height: 5rem;
                margin-bottom: 1rem;
            }
        }

        .action-buttons-container {
            padding-top: 1.5rem;
            .tv-flex-gap-wrap(0.5rem, 0.5rem);

            .action-button, .group-container {
                padding: 0 1.5rem !important;
                margin-right: 0rem !important;
                & when (@webos = true) {
                    margin-right: 0.5rem !important;
                }
                height: 3rem;
                border-radius: 2rem;
            }
        }
    }
}

@media only screen and (max-width: @minimum) {
    .meta-preview-container {
        .meta-info-container {
            .logo {
                margin: 2rem auto;
            }

            .runtime-release-info-container {
                justify-content: space-between;

                .runtime-label, .release-info-label {
                    margin: 0;
                }
            }
        }

        .action-buttons-container {
            flex-shrink: 0;
            margin-top: 3rem;
            overflow: visible;
            scrollbar-width: none;

            &::-webkit-scrollbar {
                display: none;
            }

            .action-button {
                padding: 0 1rem !important;
            }
        }
    }

    .share-prompt {
        width: auto;
    }
}

// Keep the TV cursor visible through local hover/selected overrides.
.meta-preview-container .meta-info-container .runtime-release-info-container .imdb-button-container,
.meta-preview-container .action-buttons-container .action-button.show-button {
    .tv-focus();
}

components/MetaRow/styles.less:
// Copyright (C) 2017-2023 Smart code 203358507

@import (reference) '~@stremio/stremio-colors/less/stremio-colors.less';
@import (reference) '~stremio/common/tv-focus.less';
@import (reference) '~stremio/common/screen-sizes.less';

.meta-row-container {
    overflow: visible;

    .header-container {
        display: flex;
        flex-direction: row;
        align-items: center;
        justify-content: flex-end;
        padding: 0 1rem;
        margin-bottom: 0.25rem;

        .title-container {
            flex: 1;
            max-height: 2.4em;
            font-size: 1.6rem;
            font-weight: 500;
            color: var(--primary-foreground-color);
        }

        .see-all-container {
            flex: none;
            display: flex;
            flex-direction: row;
            align-items: center;
            max-width: 12rem;
            height: 2.5rem;
            padding: 0 0.5rem 0 1rem;
            border-radius: 2.5rem;
            opacity: 0.6;

            &:hover, &:focus {
                outline: none;
                background-color: var(--overlay-color);
                opacity: 1;
            }

            .label {
                flex: 0 1 auto;
                max-height: 1.2em;
                font-size: 1rem;
                font-weight: 500;
                color: var(--primary-foreground-color);
            }

            .icon {
                flex: none;
                height: 1.5rem;
                margin-left: 0.5rem;
                color: var(--primary-foreground-color);
            }
        }
    }

    .message-container {
        max-height: 3.6em;
        padding: 0 0.5rem;
        font-size: 1.3rem;
        color: var(--primary-foreground-color);
        opacity: 0.6;
    }

    .meta-items-container {
        display: flex;
        flex-direction: row;
        align-items: stretch;
        overflow: visible;

        .meta-item {
            &.poster-shape-poster {
                flex: calc(1 / var(--poster-shape-ratio));
            }

            &.poster-shape-square {
                flex: 1;
            }

            &.poster-shape-landscape {
                flex: calc(1 / var(--landscape-shape-ratio));
            }
        }
    }
}

@media only screen and (max-width: @minimum) {
    .meta-row-container {
        .header-container {
            padding: 0 0.5rem;

            .title-container {
                margin-right: 0.5rem;
                white-space: nowrap;
                text-overflow: ellipsis;
            }
        }

        .meta-items-container {
            overflow-x: auto;
            overflow-y: hidden;
            & when (@webos = false) {
                scroll-snap-type: x mandatory;
            }
            overscroll-behavior-x: contain;
            scrollbar-width: none;

            &::-webkit-scrollbar {
                display: none;
            }

            .meta-item {
                & when (@webos = false) {
                    scroll-snap-align: start;
                }

                &:not(:first-child) {
                    margin-left: 0;
                }

                &:empty {
                    display: none;
                }

                &.poster-shape-poster, &.poster-shape-square {
                    flex: 0 0 31%;
                }

                &.poster-shape-landscape {
                    flex: 0 0 46%;
                }
            }
        }
    }
}

// Keep the TV cursor visible through local hover/selected overrides.
.meta-row-container .header-container .see-all-container {
    .tv-focus();
}

components/ModalDialog/styles.less:
// Copyright (C) 2017-2023 Smart code 203358507

@import (reference) '~@stremio/stremio-colors/less/stremio-colors.less';
@import (reference) '~stremio/common/tv-focus.less';
@import (reference) '~stremio/common/screen-sizes.less';

.modal-container {
    display: flex;
    justify-content: center;
    align-items: center;
    background-color: @color-background-dark5-40;

    .modal-dialog-container {
        position: relative;
        flex: none;
        display: flex;
        flex-direction: column;
        max-width: 80%;
        max-height: 80%;
        padding: 0 2rem;
        border-radius: var(--border-radius);
        background-color: var(--modal-background-color);
        box-shadow: var(--outer-glow);

        .modal-dialog-background {
            z-index: 0;
            position: absolute;
            top: 0;
            bottom: 0;
            left: 0;
            right: 0;
            background-size: cover;
            background-position: center;
            opacity: 0.1;
        }

        .close-button-container {
            position: absolute;
            top: 0.5rem;
            right: 0.5rem;
            width: 3rem;
            height: 3rem;
            padding: 0.5rem;
            border-radius: var(--border-radius);
            z-index: 2;

            .icon {
                display: block;
                width: 100%;
                height: 100%;
                color: var(--primary-foreground-color);
                opacity: 0.4;
            }

            &:hover,
            &:focus {
                .icon {
                    opacity: 1;
                    color: var(--primary-foreground-color);
                }
            }

            &:focus {
                outline-color: var(--primary-foreground-color);
            }
        }

        .modal-dialog-content {
            z-index: 1;
            position: relative;
            overflow-y: auto;

            .title-container {
                flex: 1 0 auto;
                display: flex;
                align-items: center;
                height: 4.5rem;
                font-size: 1.2rem;
                font-weight: 500;
                color: var(--primary-foreground-color);
            }

            .body-container {
                flex: 1;
                align-self: stretch;
                overflow: visible;
                padding: 2rem 0;

                &:last-child {
                    margin-bottom: 2rem;
                }
            }

            .buttons-container {
                flex: none;
                align-self: stretch;
                display: flex;
                flex-direction: row;
                flex-wrap: wrap;

                &:last-child {
                    margin: 2rem 0;
                }
            }
        }
    }
}

.action-button {
    flex: 1;
    display: flex;
    flex-direction: row;
    align-items: center;
    justify-content: center;
    height: 3.5rem;
    border-radius: 3.5rem;
    padding: 1.2rem;
    background-color: var(--secondary-accent-color);

    &:hover {
        background-color: transparent;
        outline: var(--focus-outline-size) solid var(--secondary-accent-color);
    }

    &:focus {
        outline-color: var(--primary-foreground-color);
    }

    &:not(:last-child) {
        margin-right: 1rem;
    }

    .icon {
        flex: none;
        width: 1.2rem;
        height: 1.2rem;
        margin-right: .5rem;
        color: var(--primary-foreground-color);
    }

    .label {
        flex-grow: 0;
        flex-shrink: 1;
        flex-basis: auto;
        max-height: 3.6em;
        font-size: 1.1rem;
        font-weight: 700;
        text-align: center;
        color: var(--primary-foreground-color);
