        &.error {
            border-color: var(--danger-accent-color);
        }

        &.selected {
            .inner-circle {
                background-color: var(--primary-accent-color);
                opacity: 1;
            }
        }

        &:focus {
            outline-style: solid;
        }
    }
}

.radio-button .radio-container:focus, .radio-button .radio-container:focus-within {
