                    padding: 0 0.5rem;
                    max-width: 10rem;

                    &:not(:only-child) {
                        max-width: 5rem;
                    }

                    .flag-icon {
                        height: 1.15rem;
                        width: 1.15rem;
                        margin-right: 0.25rem;
                        color: var(--secondary-foreground-color);
                    }

                    .flag-label {
                        font-size: 0.8rem;
                        font-weight: 800;
                        white-space: nowrap;
                        text-overflow: ellipsis;
                        text-transform: uppercase;
                        color: var(--secondary-foreground-color);
                    }
                }

                .upcoming-container {
                    background-color: var(--secondary-accent-color);
                }

                .watched-container {
                    background-color: var(--tertiary-accent-color);
                }
            }
        }
    }

    .play-button-container {
        flex: none;
        display: flex;
        align-items: center;
        justify-content: center;
        width: 3rem;
        height: 3rem;
        margin-right: 0.5rem;
        border-radius: 50%;
        color: var(--primary-foreground-color);
        background-color: var(--overlay-color);

        &:hover,
        &:focus {
            background-color: var(--secondary-accent-color);
        }

        .play-icon {
            width: 1.5rem;
            height: 1.5rem;
        }
    }

    &.selected {
        animation: border 3s ease-in-out forwards;
    }

    @keyframes border {
        0% {
            border: 0.15rem solid var(--primary-accent-color);
        }
        100% {
            border: 0.15rem solid transparent;
        }
    }


    .context-menu-container {
        max-width: calc(90% - 1.5rem);
        z-index: 2;

        .context-menu-content {
            --spatial-navigation-contain: contain;

            .context-menu-option-container {
                display: flex;
                flex-direction: row;
                align-items: center;
                padding: 1rem 1.5rem;

                &:hover,
                &:focus {
                    background-color: var(--overlay-color);
                }

                .context-menu-option-label {
                    font-size: 1rem;
                    font-weight: 500;
                    color:var(--primary-foreground-color);
                }
            }
        }
    }
}

@media only screen and (max-width: @minimum) {
    .video-container {
        .context-menu-container {
            &.menu-direction-top-left,
            &.menu-direction-bottom-left {
                right: 1.5rem;
            }

            &.menu-direction-top-right,
            &.menu-direction-bottom-right {
                left: 1.5rem;
            }

            &.menu-direction-top-left,
            &.menu-direction-top-right {
                bottom: 90%;
            }

            &.menu-direction-bottom-left,
            &.menu-direction-bottom-right {
                top: 90%;
            }
        }
    }
}

