@import (reference) '~@stremio/stremio-colors/less/stremio-colors.less';
@import (reference) '~stremio/common/tv-focus.less';
@import (reference) '~stremio/common/screen-sizes.less';

.error-container {
    position: relative;
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    .tv-flex-gap(1rem, 1rem, column);

    .error-image {
        flex: none;
        width: 12rem;
        height: 12rem;
        object-fit: contain;
        object-position: center;
        opacity: 0.9;
    }

    .info {
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        .tv-flex-gap(0.5rem, 0.5rem, column);

        .title {
            font-size: 2rem;
            color: var(--primary-foreground-color);
        }

        .message {
            position: relative;
            max-width: 40rem;
            display: -webkit-box;
            font-size: 1.5rem;
            color: var(--primary-foreground-color);
            opacity: 0.6;
            text-align: center;
            text-overflow: ellipsis;
            -webkit-box-orient: vertical;
            -webkit-line-clamp: 5;
        }
    }

    .buttons-container {
        flex: none;
        align-self: stretch;
        margin: 0 2rem;
        display: flex;
        flex-direction: row;
        flex-wrap: wrap;
        align-items: center;
        justify-content: center;
        margin-top: 1rem;
        .tv-flex-gap-wrap(1.5rem, 1.5rem);

        .button-container {
            flex-grow: 0;
            flex-shrink: 1;
            flex-basis: auto;
            display: flex;
            flex-direction: row;
            align-items: center;
            justify-content: center;
            padding: 0 2.5rem;
            min-width: 8rem;
            height: 3.5rem;
            border-radius: 3.5rem;
            background-color: var(--overlay-color);

            &:hover {
                outline: var(--focus-outline-size) solid var(--primary-foreground-color);
                background-color: transparent;
            }

            &:active {
                outline: none;
            }

            &:global(.disabled) {
                opacity: 0.3;
            }

            .label {
                flex-grow: 0;
                flex-shrink: 1;
                flex-basis: auto;
                max-height: 2.4em;
                font-size: 1.1rem;
                font-weight: 500;
                text-align: center;
                color: var(--primary-foreground-color);
            }
        }
    }
}

// Keep the TV cursor visible through local hover/selected overrides.
.error-container .buttons-container .button-container {
    .tv-focus();
}

