// Copyright (C) 2017-2024 Smart code 203358507

@import (reference) '~@stremio/stremio-colors/less/stremio-colors.less';
@import (reference) '~stremio/common/screen-sizes.less';

.metadetails-container {
    display: flex;
    flex-direction: column;
    width: 100%;
    height: 100%;
    padding-left: var(--safe-area-inset-left);
    padding-right: var(--safe-area-inset-right);
    box-sizing: border-box;

    .background-image-layer {
        position: fixed;
        top: 0;
        right: 0;
        bottom: 0;
        left: 0;
        z-index: -1;
        background-color: var(--modal-background-color);

        .background-image {
            pointer-events: none; 
            display: block;
            width: 100%;
            height: 100%;
            object-fit: cover;
            object-position: right;
            opacity: 0.3;
        }
    }

    .nav-bar {
        z-index: 1;
        flex: none;
        align-self: stretch;
    }

    .metadetails-content {
        flex: 1;
        align-self: stretch;
        position: relative;
        z-index: 0;
        display: flex;
        flex-direction: row;
        margin-top: calc(var(--top-overlay-size) * -1);
        padding-top: var(--top-overlay-size);
        padding-bottom: var(--safe-area-inset-bottom, 0rem);

        .meta-message-container {
            align-self: stretch;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            padding: 2rem;
            width: 100%;
            height: 100%;

            .image {
                flex: none;
                width: 12rem;
                height: 12rem;
                max-width: 100%;
                margin-bottom: 1rem;
                object-fit: contain;
                object-position: center;
                opacity: 0.9;
            }

            .message-label {
                flex: none;
                align-self: stretch;
                font-size: 2rem;
                text-align: center;
                color: var(--primary-foreground-color);
            }
        }

        .meta-preview {
            flex: 0 1 auto;
            align-self: stretch;
            padding: 0 4rem 2rem 4rem;

            & when (@webos = false) {
                padding-left: max(1rem, calc(4rem - var(--safe-area-inset-left)));
            }
            & when (@webos = true) {
                // T2.8: restore a compile-time clamp if the left inset exceeds 3rem.
                padding-left: calc(4rem - var(--safe-area-inset-left));
            }
        }

        .spacing {
            flex: 1;
        }

        .videos-list, .streams-list {
            flex: 0 0 30rem;
            align-self: stretch;
            border-radius: var(--border-radius) 0 0 var(--border-radius);
            background-color: rgba(12, 11, 17, 0.95);

            @supports (backdrop-filter: blur(1px)) {
                background-color: rgba(0, 0, 0, 0.4);
                backdrop-filter: blur(15px);
            }
        }
    }
}

@media @phone-landscape {
    .metadetails-container {
        .metadetails-content {
            .meta-preview {
                padding: 0 1.5rem 1rem;
            }
        }
    }
}

@media only screen and (max-width: @minimum) {
    .metadetails-container {
        .background-image-layer {
            .background-image {
                object-position: center;
            }
        }

        .metadetails-content {
            display: block;
            overflow-y: auto;
            padding-top: calc(var(--top-overlay-size) + var(--safe-area-inset-top));

            .spacing {
                display: none;
            }

            .meta-preview {
                padding: 0 1.5rem 2rem;
            }

            .videos-list, .streams-list {
                border-radius: var(--border-radius) var(--border-radius) 0 0;
            }
        }
    }
}

