    width: 100%;
    height: 100%;
    background-color: @background-color;

    .layer {
        position: absolute;
        top: 0;
        left: 0;
        right: 0;
        bottom: 0;
        z-index: 0;

        &.buffering-layer, &.error-layer {
            background: transparent;
        }

        &.background-layer {
            .image {
                width: 100vw;
                height: 100vh;
                object-fit: cover;
                opacity: 0.6;
            }
        }

        &.nav-bar-layer {
            left: var(--safe-area-inset-left);
            right: var(--safe-area-inset-right);
            bottom: initial;
            background: transparent;
            overflow: visible;

            &::before {
                position: absolute;
                right: 0;
                top: 0;
                left: 0;
                height: 8rem;
                z-index: -1;
                content: "";
                background: linear-gradient(to bottom, rgba(0, 0, 0, 0.35) 0%, transparent 100%);
                pointer-events: none;
            }

            .nav-bar-button-container {
                &:hover {
                    background: transparent;
                }

                .nav-bar-icon {
                    color: var(--primary-foreground-color);
                }
            }

            .nav-bar-title {
                color: var(--primary-foreground-color);
            }
        }

        &.side-drawer-button-layer {
            position: fixed;
            top: 50%;
            right: -4rem;
            left: initial;
            transform: translateY(-50%);
        }

        &.control-bar-layer {
            left: var(--safe-area-inset-left);
            right: var(--safe-area-inset-right);
            top: initial;
            overflow: visible;
            padding-bottom: calc(0.5rem + var(--safe-area-inset-bottom));

            &::before {
                position: absolute;
                right: 0;
                bottom: 0;
                left: 0;
                height: 10rem;
                z-index: -1;
                content: "";
                background: linear-gradient(to top, rgba(0, 0, 0, 0.35) 0%, transparent 100%);
                pointer-events: none;
            }
        }

        &.indicator-layer {
            top: initial;
            left: 0;
            right: 0;
            bottom: 10rem;
        }

        &.menu-layer {
            top: initial;
            left: initial;
            right: 4rem;
            bottom: 7.5rem;
            max-height: calc(100% - 13rem);
            max-width: calc(100% - 4rem);
            border-radius: var(--border-radius);
            background-color: var(--modal-background-color);
            box-shadow: 0 1.35rem 2.7rem @color-background-dark5-40,
                0 1.1rem 0.85rem @color-background-dark5-20;
            @supports (backdrop-filter: blur(1px)) {
                backdrop-filter: blur(15px);
            }
            overflow: auto;
        }

        &.side-drawer-layer {
            bottom: 0;
            right: 0;
            left: initial;
            bottom: initial;
        }
    }
}

@media screen and (max-width: @xsmall) {
    .player-container {
        .layer {
            &.side-drawer-button-layer {
                right: -2rem;
            }
        }
    }
}

@media (orientation: portrait) and (max-width: @minimum) {
    .player-container {
        .layer {
            &.menu-layer {
                right: 2.5rem;
                bottom: 11rem;
            }
        }
    }
}

