@import (reference) '~@stremio/stremio-colors/less/stremio-colors.less';
@import (reference) '~stremio/common/screen-sizes.less';

.control-bar-container {
    padding: 0 2rem;

    .seek-bar {
        --track-size: 0.4rem;
        --thumb-size: 1.2rem;

        height: 2.5rem;
    }

    .control-bar-buttons-container {
        display: flex;
        flex-direction: row;
        align-items: center;
        .tv-flex-gap(0.25rem, 0.25rem, row);

        .control-bar-button {
            flex: none;
            width: 4rem;
            height: 4rem;
            display: flex;
            justify-content: center;
            align-items: center;
            border-radius: 0.75rem;
            transition: background-color 150ms ease;

            &:hover:not(:global(.disabled)) {
                background-color: var(--overlay-color);
            }

            &:global(.disabled) {
                .icon {
                    opacity: 0.4;
                }
            }

            .icon {
                flex: none;
                width: 2.2rem;
                height: 2.2rem;
                color: var(--primary-foreground-color);
                transition: transform 100ms ease;
            }
        }

        .volume-slider {
            --track-size: 0.35rem;
            --thumb-size: 1rem;

            flex: 0 1 10rem;
            height: 4rem;
            margin: 0 0.5rem;
        }

        .spacing {
            flex: 1;
        }

        .control-bar-buttons-menu-button {
            flex: none;
            width: 4rem;
            height: 4rem;
            display: none;
            justify-content: center;
            align-items: center;
            border-radius: 0.75rem;
            transition: background-color 150ms ease;

            &:hover {
                background-color: var(--overlay-color);
            }

            .icon {
                flex: none;
                width: 2.2rem;
                height: 2.2rem;
                color: var(--primary-foreground-color);
            }
        }

        .control-bar-buttons-menu-container {
            flex: none;
            display: flex;
            flex-direction: row;
            .tv-flex-gap(0.25rem, 0.25rem, row);
        }
    }
}

@media only screen and (max-width: @minimum) {
    .control-bar-container {
        padding: 0;

        .seek-bar {
            margin: 0 1.5rem;
        }

        .control-bar-buttons-container {
            position: relative;
            padding: 0 0.5rem;
            overflow: visible;
            .tv-flex-gap(0.15rem, 0.15rem, row);

            .volume-slider {
                display: none;
            }

            .control-bar-buttons-menu-button {
                display: flex;
            }

            .control-bar-buttons-menu-container {
                position: absolute;
                right: 0rem;
                bottom: 4.5rem;
                padding: 0.5rem;
                margin: 0.5rem;
                .tv-flex-gap(0.15rem, 0.15rem, row);
                max-width: calc(100dvw - 1rem);
                border-radius: var(--border-radius);
                background-color: var(--modal-background-color);
                box-shadow: 0 1.35rem 2.7rem @color-background-dark5-40,
                    0 1.1rem 0.85rem @color-background-dark5-20;
                overflow-x: auto;

                &:not(:global(.open)) {
                    display: none;
                }
            }
        }
    }
}

