routes/Player/NextVideoPopup/styles.less:
// Copyright (C) 2017-2023 Smart code 203358507

@import (reference) '~@stremio/stremio-colors/less/stremio-colors.less';
@import (reference) '~stremio/common/tv-focus.less';
@import (reference) '~stremio/common/screen-sizes.less';

.next-video-popup-container {
    display: flex;
    flex-direction: row;
    width: 38rem;
    min-height: 13rem;
    animation: slide-fade-in 0.5s ease-in;

    @keyframes slide-fade-in {
        0% {
            opacity: 0;
            transform: translateX(calc(40rem + 2rem));
        }

        100% {
            opacity: 1;
            transform: translateX(0);
        }
    }

    .poster-container {
        flex: 1 1 25%;
        display: flex;
        justify-content: center;
        align-items: center;
        background-color: var(--overlay-color);

        .poster-image {
            flex: none;
            width: 100%;
            height: 100%;
            object-position: center;
            object-fit: cover;

            &.blurred {
                filter: blur(0.5rem);
                -webkit-filter: blur(0.5rem);
            }
        }

        .placeholder-icon {
            flex: none;
            width: 80%;
            height: 50%;
            color: var(--primary-foreground-color);
        }
    }

    .info-container {
        flex: 1 1 55%;
        display: flex;
        flex-direction: column;

        .details-container {
            flex: auto;
            display: flex;
            flex-direction: column;
            .tv-flex-gap(1rem, 1rem, column);
            padding: 1.5rem 2rem;

            .name {
                flex: none;
                align-self: stretch;
                max-height: 2.4em;
                font-weight: 700;
                color: var(--primary-accent-color);

                .label {
                    color: var(--primary-foreground-color);
                }
            }

            .title {
                flex: none;
                align-self: stretch;
                max-height: 2.4em;
                font-weight: 500;
                color: var(--primary-foreground-color);
            }
        }

        .buttons-container {
            display: flex;
            flex-direction: row;
            justify-content: space-between;
            .tv-flex-gap(1rem, 1rem, row);
            padding: 0 1rem 1.5rem;

            .spacing {
                flex: 0 0 50%;
            }

            .button-container {
                flex: 0 1 50%;
                display: flex;
                flex-direction: row;
                align-items: center;
                justify-content: center;
                .tv-flex-gap(1rem, 1rem, row);
                height: 3.5rem;
                padding: 0 1rem;
                border-radius: 1.75rem;

                &.play-button {
                    background-color: var(--primary-accent-color);

                    .icon {
                        color: var(--primary-foreground-color);
                    }

                    .label {
                        color: var(--primary-foreground-color);
                    }

                    &:hover {
                        outline: var(--focus-outline-size) solid var(--primary-accent-color);
                        background-color: transparent;
                    }
                }

                .icon {
                    flex: none;
                    width: 1.4rem;
                    height: 1.4rem;
                    color: var(--primary-foreground-color);
                }

                .label {
                    flex: none;
                    max-height: 2.4em;
                    font-size: 1.1rem;
                    font-weight: 500;
                    color: var(--primary-foreground-color);
                }

                &.dismiss {
                    opacity: 0.6;
                }

                &:hover, &:focus {
                    background-color: var(--overlay-color);
                }
            }
        }
    }
}

@media @phone-portrait {
    .next-video-popup-container {
        .info-container {
            .buttons-container {
                .tv-flex-gap(0.5rem, 0.5rem, row);

                .button-container {
                    margin-left: 0rem;

                    .icon {
                        margin-right: 0rem;
                    }
    
                    .label {
                        display: none;
                    }
                }
            }
        }
    }
}

// Keep the TV cursor visible through local hover/selected overrides.
.next-video-popup-container .info-container .buttons-container .button-container.play-button {
    .tv-focus();
}

routes/Player/SideDrawer/SideDrawer.less:
// Copyright (C) 2017-2024 Smart code 203358507

@import (reference) '~stremio/common/screen-sizes.less';

:import('~stremio/components/MetaPreview/styles.less') {
    description-container: description-container;
    action-buttons-container: action-buttons-container;
}

:import('~stremio/components/MultiselectMenu/Dropdown/Dropdown.less') {
    dropdown: dropdown;
    open: open;
}

@padding: 1rem;

.side-drawer {
    display: flex;
    flex-direction: column;
    padding: @padding;
    padding-top: calc(@padding + var(--safe-area-inset-top));
    height: if(@webos = true, 100vh, 100dvh);
    max-width: 35rem;
    overflow-y: auto;
    position: relative;
    border-top-left-radius: var(--border-radius);
    border-bottom-left-radius: var(--border-radius);
    background-color: var(--modal-background-color);
    box-shadow: 0 1.35rem 2.7rem var(--color-background-dark5-40), 0 1.1rem 0.85rem var(--color-background-dark5-20);
    @supports (backdrop-filter: blur(1px)) {
        backdrop-filter: blur(15px);
    }
    transition: transform 0.3s ease-in-out;
    z-index: 1;

    // Safari has a compositing bug where transform animations on a parent with
    // scrollable children causes the video player element to shift left during the animation.
    // Disable the slide animation on Safari until WebKit resolves this.
    @supports (hanging-punctuation: first) and (-webkit-appearance: none) {
        &:global(.slide-left-enter),
        &:global(.slide-left-active),
        &:global(.slide-left-exit) {
            transition: none;
        }
    }

    .close-button {
        display: none;
        position: absolute;
        top: calc(1.3rem + var(--safe-area-inset-top));
        right: 1.3rem;
        padding: 0.5rem;
        background-color: transparent;
        cursor: pointer;
        z-index: 2;
        border-radius: var(--border-radius);
        transition: 0.3s all ease-in-out;
        -webkit-tap-highlight-color: transparent;

        .icon {
            color: var(--primary-foreground-color);
            width: 2rem;
            height: 2rem;
            opacity: 0.6;
            transition: 0.3s opacity ease-in-out;
        }

        &:hover {
            background-color: var(--overlay-color);

            .icon {
                opacity: 1;
            }
        }
    }

    .info {
        padding: @padding;
        min-height: 0;
        overflow-y: auto;

        .side-drawer-meta-preview {
            .description-container {
                display: -webkit-box;
                -webkit-line-clamp: 4;
                -webkit-box-orient: vertical;
            }

            .action-buttons-container {
                padding-top: 0;
                margin-top: 0;
            }
        }
    }

    .series-content {
        flex: 2;
        display: flex;
        flex-direction: column;
        min-height: 0;

        .videos {
            flex: 1;
            min-height: 0;
            overflow-y: auto;
        }
    }
}

@media @phone-portrait {
    .side-drawer {
        max-width: 100dvw;

        .close-button {
            display: block;
        }
    }
}

@media @phone-landscape {
    .side-drawer {
        max-width: 50dvw;

        .info {
            max-height: 40dvh;
        }

        .dropdown.open {
            max-height: calc(3rem * 4);
        }
    }
}

@media screen and (max-width: @xxsmall) {
    .side-drawer {
        padding: calc(@padding / 2);

        .info {
            padding: calc(@padding / 2);
        }
    }
}

// Preserve hover transitions without animating the TV outline.
.side-drawer .close-button when (@webos = true) {
    transition-property: background-color;
}

