@import (reference) '~stremio/common/screen-sizes.less';

.disable-cell-items() {
    .cell {
        .items {
            .item {
                pointer-events: none;
            }
        }
    }
}

.compact-items() {
    .cell {
        .items {
            padding: 1px;
            .tv-flex-gap(0.15rem, 0.15rem, row);
        }
    }
}

.cell {
    position: relative;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    .tv-flex-gap(0.5rem, 0.5rem, column);
    background-color: var(--overlay-color);
    border: 0.15rem solid transparent;
    overflow: hidden;
    cursor: pointer;
    transition: border-color 0.1s ease-out;

    &:first-child {
        border-radius: var(--border-radius) 0 0 0;
    }

    &:nth-child(7) {
        border-radius: 0 var(--border-radius) 0 0;
    }

    &:last-child {
        border-radius: 0 0 var(--border-radius) 0;
    }

    .heading {
        position: relative;
        display: flex;
        align-items: flex-start;

        .day {
            flex: none;
            position: relative;
            display: flex;
            align-items: center;
            justify-content: center;
            height: 2rem;
            width: 2rem;
            border-radius: 100%;
            font-size: 1rem;
            font-weight: 500;
            color: var(--primary-foreground-color);
        }
    }

    .items {
        position: relative;
        display: flex;
        flex-direction: row;
        .tv-flex-gap(0.2rem, 0.2rem, row);
        padding: 0.1rem;
        flex: 1 1 60%;
        overflow-x: auto;
        overflow-y: hidden; 
        min-width: 0;

        .item {
            flex: none;
            display: flex;
            align-items: center;
            justify-content: center;
            height: 100%;
            aspect-ratio: 2 / 3;
            border-radius: calc(var(--border-radius) / 2);
            max-height: 100%;
            max-width: 100%;

            .icon {
                flex: none;
                z-index: 1;
                position: absolute;
                width: 2rem;
                height: 2rem;
                padding: 0.5rem;
                border-radius: 50%;
                color: var(--primary-foreground-color);
                background-color: var(--secondary-accent-color);
                opacity: 0;
            }

            .poster {
                height: auto;
                max-height: 100%;
                aspect-ratio: 2 / 3;
                object-fit: cover;
                border-radius: inherit
            }

            .icon, .poster {
                transition: opacity 0.1s ease-out;
            }

            &:hover {
                .icon {
                    opacity: 1;
                }

                .poster {
                    opacity: 0.5;
                }
            }
        }
    }

    .more {
        display: none;
        flex: none;
        width: 2rem;
        height: 2rem;
        padding: 0.5rem;
        align-self: center;
        color: var(--primary-foreground-color);
    }

    &.today {
        .heading {
            padding: 0.3rem;
            .day {
                background-color: var(--primary-accent-color);
                height: 1.5rem;
                width: 1.5rem;
            }
        }
    }

    &.active {
        border-color: var(--primary-foreground-color);
    }

    @media (pointer: fine) {
        &:not(.active):hover {
            border-color: var(--overlay-color);
        }
    }
}

// Chromium 68 (webOS TV 5) has no `aspect-ratio` and cannot propagate an
// intrinsic ratio from a replaced child to the shrink-wrapped item box, so the
// item width is pinned by a runtime measurement in Cell.tsx. This block keeps
// the CSS half of the fallback: a definite height for the items row (old Blink
// cannot resolve percentage heights across the grid > flex chain), vertical
// centering for the icon without static-position flex behavior and the poster
// stretched to fill the measured item box with `object-fit: cover`.
@supports not (aspect-ratio: 2 / 3) {
    .cell {
        .items {
            flex-basis: auto;
            height: calc(100% - 2rem);

            .item {
                position: relative;
                display: inline-block;

                .icon {
                    top: 50%;
                    left: 50%;
                    transform: translate(-50%, -50%);
                }

                .poster {
                    position: absolute;
                    top: 0;
                    right: 0;
                    bottom: 0;
                    left: 0;
                    width: 100%;
                    height: 100%;
                }
            }
        }
    }
}

@media only screen and (max-width: @minimum) {
    .disable-cell-items();
}

@media @phone-portrait {
