            &:hover {
                background-color: transparent;
                border: 2px solid var(--primary-foreground-color);
            }
        }

        .reload {
            display: flex;
            .tv-flex-gap(0, 0.5rem, row);
            align-items: center;
            justify-content: center;
            padding: 0.5rem 1.5rem;
            background-color: var(--overlay-color);
            border-radius: 1.5rem;
            transition: 0.3s all ease-in-out;
            color: var(--primary-foreground-color);
            border: 2px solid transparent;

            .icon {
                width: 1rem;
                height: 1rem;
                color: var(--primary-foreground-color);
            }

            &:hover {
                background-color: transparent;
                border: 2px solid var(--primary-foreground-color);
            }
        }
    }
}

// Preserve hover transitions without animating the TV outline.
.wrapper .footer .add-url, .wrapper .footer .reload {
    & when (@webos = true) { transition-property: background-color, border-color; }
}

